<?php
namespace Tests\Feature;
use App\Models\{BookingServis,JenisServis,Servis,ServisSparepart,Sparepart,User}; use App\Services\{BookingServisService,ServisService,ServisSparepartService}; use Illuminate\Foundation\Testing\DatabaseTransactions; use Illuminate\Support\Facades\Schema; use RuntimeException; use Tests\TestCase;
class ServisSparepartStage5BTest extends TestCase { use DatabaseTransactions;
 private function user(string $r):User{return User::whereHas('role',fn($q)=>$q->where('nama_role',$r))->firstOrFail();}
 private function freshService():Servis{$u=$this->user('pelanggan');$v=$u->pelanggan->kendaraan()->create(['merk'=>'QA','model'=>'Part','nomor_polisi'=>'PT-'.random_int(1000,9999),'kilometer'=>30000,'status'=>'aktif']);$t=JenisServis::where('status','aktif')->firstOrFail();$b=app(BookingServisService::class)->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$t->id_jenis_servis,now()->addDay()->toDateString(),'10:00',null,null);$b->forceFill(['status'=>'diterima'])->save();$s=app(ServisService::class)->createFromBooking($b->id_booking_servis,$this->user('petugas')->petugas->id_petugas,null,null);return app(ServisService::class)->updateInspection($s->id_servis,'Diagnosis',null);}
 public function test_baseline_import_and_stock_match():void{$this->assertSame(2,ServisSparepart::count());$this->assertDatabaseHas('servis_sparepart',['id_servis_sparepart'=>1,'id_servis'=>1,'id_sparepart'=>1,'jumlah'=>1]);$this->assertSame(5,(int)Sparepart::find(1)->stok);}
 public function test_add_draft_does_not_change_stock_or_history():void{$s=$this->freshService();$p=Sparepart::where('status','aktif')->firstOrFail();$stock=(int)$p->stok;$history=\App\Models\RiwayatStok::count();$item=app(ServisSparepartService::class)->add($s->id_servis,$p->id_sparepart,1);$this->assertSame($stock,(int)$p->fresh()->stok);$this->assertSame($history,\App\Models\RiwayatStok::count());$this->assertSame('35000.00',$item->fresh()->harga_satuan);$this->assertSame('35000.00',$item->fresh()->subtotal);}
 public function test_duplicate_add_merges_quantity_without_double_stock_mutation():void{$s=$this->freshService();$p=Sparepart::where('status','aktif')->firstOrFail();$svc=app(ServisSparepartService::class);$a=$svc->add($s->id_servis,$p->id_sparepart,1);$b=$svc->add($s->id_servis,$p->id_sparepart,2);$this->assertSame($a->id_servis_sparepart,$b->id_servis_sparepart);$this->assertSame(3,(int)$b->fresh()->jumlah);$this->assertSame(5,(int)$p->fresh()->stok);}
 public function test_zero_negative_and_insufficient_quantity_are_rejected():void{$s=$this->freshService();$p=Sparepart::where('status','aktif')->firstOrFail();$svc=app(ServisSparepartService::class);foreach([0,-1,((int)$p->stok)+1] as $qty){try{$svc->add($s->id_servis,$p->id_sparepart,$qty);$this->fail('Quantity should be rejected');}catch(RuntimeException $e){$this->assertTrue(true);}}$this->assertSame(0,ServisSparepart::where('id_servis',$s->id_servis)->count());}
 public function test_server_price_and_subtotal_ignore_client_values():void{$s=$this->freshService();$p=Sparepart::where('status','aktif')->firstOrFail();$item=app(ServisSparepartService::class)->add($s->id_servis,$p->id_sparepart,2);$this->assertSame((string)$p->harga_jual,$item->harga_satuan);$this->assertSame('70000.00',$item->subtotal);}
 public function test_inactive_sparepart_is_rejected():void{$s=$this->freshService();$p=Sparepart::firstOrFail();$p->update(['status'=>'nonaktif']);$this->expectException(\Illuminate\Database\Eloquent\ModelNotFoundException::class);app(ServisSparepartService::class)->add($s->id_servis,$p->id_sparepart,1);}
 public function test_draft_edit_and_delete_do_not_change_stock():void{$s=$this->freshService();$p=Sparepart::where('status','aktif')->firstOrFail();$svc=app(ServisSparepartService::class);$item=$svc->add($s->id_servis,$p->id_sparepart,1);$svc->add($s->id_servis,$p->id_sparepart,2);$svc->remove($s->id_servis,$item->id_servis_sparepart);$this->assertSame(5,(int)$p->fresh()->stok);$this->assertSame(0,ServisSparepart::where('id_servis',$s->id_servis)->count());}
 public function test_final_service_draft_cannot_change():void{$s=$this->freshService();$s->forceFill(['status'=>'selesai','id_transaksi'=>null])->save();$this->expectException(RuntimeException::class);app(ServisSparepartService::class)->add($s->id_servis,1,1);}
 public function test_customer_mutation_and_idor_are_blocked():void{$s=$this->freshService();$owner=$s->pelanggan->user;$this->actingAs($owner)->post('/pelanggan/servis/'.$s->id_servis.'/sparepart',['id_sparepart'=>1,'jumlah'=>1])->assertNotFound();$other=User::whereHas('role',fn($q)=>$q->where('nama_role','pelanggan'))->where('id_user','<>',$owner->id_user)->first();if($other)$this->actingAs($other)->get('/pelanggan/servis/'.$s->id_servis)->assertForbidden();}
 public function test_admin_and_petugas_routes_exist_but_payment_workflow_is_deferred():void{$this->assertTrue(Schema::hasTable('servis_sparepart'));$this->assertTrue(Schema::hasTable('transaksi'));$this->assertTrue(Schema::hasTable('pembayaran'));$this->actingAs($this->user('admin'))->get('/admin/servis')->assertOk();$this->actingAs($this->user('petugas'))->get('/petugas/servis')->assertOk();}
 public function test_work_order_relation_is_eager_loadable():void{$s=$this->freshService();app(ServisSparepartService::class)->add($s->id_servis,1,1);$loaded=Servis::with('sparepartItems.sparepart')->findOrFail($s->id_servis);$this->assertSame(1,$loaded->sparepartItems->first()->sparepart->id_sparepart);}
}
